// @vitest-environment jsdom
import RAPIER from '@dimforge/rapier3d-compat';
import { beforeAll, describe, expect, it } from 'vitest';
import { HoleSceneBuilder } from '../core/HoleSceneBuilder';
import type { Hole, ObstacleDescriptor } from '../courses/types';
import { PhysicsWorld } from '../physics/PhysicsWorld';
import { HoleRuntime } from './HoleRuntime';

const v = (x: number, y: number, z: number) => ({ x, y, z });

const SWING_ANGLE = 0.6;
const ARM_LENGTH = 1.6;
const PENDULUM_BASE = v(0, 1.5, 6);
const DOOR_BASE = v(-2, 0.85, 10);
const DOOR_TRAVEL = 2;
const SHELF_BASE = v(2, 0.8, 14);
const SHELF_TRAVEL = 3;

const obstacles: ObstacleDescriptor[] = [
  {
    id: 'clock-pendulum',
    type: 'pendulum',
    transform: { position: PENDULUM_BASE },
    size: v(0.5, 2, 0.5),
    motion: { kind: 'swing', axis: v(0, 0, 1), speed: 1.4, armLength: ARM_LENGTH, swingAngle: SWING_ANGLE },
  },
  {
    id: 'cellar-door',
    type: 'door',
    transform: { position: DOOR_BASE },
    size: v(2.4, 1.6, 0.4),
    motion: {
      kind: 'translate',
      axis: v(1, 0, 0),
      speed: 1.2,
      distance: DOOR_TRAVEL,
      loop: 'ping-pong',
      pauseSeconds: 0.5,
    },
  },
  {
    id: 'sliding-shelf',
    type: 'sliding-wall',
    transform: { position: SHELF_BASE },
    size: v(2.4, 1.6, 0.5),
    motion: { kind: 'translate', axis: v(1, 0, 0), speed: 1, distance: SHELF_TRAVEL, loop: 'loop' },
  },
];

const hole: Hole = {
  id: 'mover-lab',
  name: 'Mover Lab',
  par: 3,
  spawn: v(0, 0.3, 0),
  cup: { position: v(0, 0, 18), radius: 0.2, captureDepth: 0.25 },
  bounds: { min: v(-8, -2, -2), max: v(8, 6, 20) },
  surfaces: [
    { id: 'fairway', transform: { position: v(0, -0.25, 9) }, shape: 'box', size: v(12, 0.5, 24), material: 'green' },
  ],
  obstacles,
};

interface Sample {
  x: number;
  y: number;
  angle: number;
}

interface Rig {
  runtime: HoleRuntime;
  /** Drives the hole clock and returns one pose sample per fixed step. */
  sample(id: string, seconds: number): Sample[];
  dispose(): void;
}

function createRig(): Rig {
  const physics = new PhysicsWorld();
  const builder = new HoleSceneBuilder();
  const runtime = new HoleRuntime(physics, hole, builder);
  return {
    runtime,
    sample(id, seconds) {
      const samples: Sample[] = [];
      const steps = Math.round(seconds / physics.fixedStep);
      for (let step = 0; step < steps; step += 1) {
        physics.step(physics.fixedStep, (fixed) => runtime.update(fixed));
        const pose = runtime.moverPose(id);
        if (!pose) throw new Error('no mover named ' + id);
        samples.push({
          x: pose.position.x,
          y: pose.position.y,
          angle: 2 * Math.atan2(pose.rotation.z, pose.rotation.w),
        });
      }
      return samples;
    },
    dispose() {
      runtime.dispose();
      builder.dispose();
      physics.dispose();
    },
  };
}

beforeAll(async () => {
  await RAPIER.init();
});
EOF
